INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1537189-ae426', 'stk-alialrajjal', 'AE 426', 'info', '{"desc": "المواضيع التي يغطيها المقرر\nالمقرر يتكلم عن كيف تتحرك الطائره وتغير مسارها وتكون مستقره\nبتبدا بمعادلة الحركة وكيف ممكن تستخدمها بعدها بتاخذ (earth frame & body frame)\nوتتعلم عن جميع الحركات الممكنه للطائره (roll , yaw, lift …etc)\nوبتعلم عن كيف ممكن تعمل نظام الكتروني يضمن استقرار الطائره شبيه بالي تعلمناه في AE313/AE314\n\nالكتاب المستخدم للمقرر\nThomas R. Yechout, Introduction to Aircraft Flight Mechanics: Performance, Static Stability, Dynamic Stability, Classical Feedback Control, and State-space Foundations, 2nd Ed., AIAA, 2014.\n\nاخذته في 231", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae-426-flight-dynamics-i/120809/2", "user": "AliAlrajjal", "ts": 1704225713000, "tid": 120809, "pn": 2}}', 1704225713000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
